def answer() -> dict[str, list[int]]:
    # logic to compute total salaries per month
    import pandas as pd
    import ast
    from datetime import datetime
    from collections import defaultdict

    employees = pd.read_csv('/app/dataset/employees.csv')
    timesheet = pd.read_csv('/app/dataset/timesheet.csv')
    tasks = pd.read_csv('/app/dataset/tasks.csv')

    task_lookup = {int(t['task_id']): t for _, t in tasks.iterrows()}
    emp_map = {
        62020111425: 65020111422,
        68011910138: 68011810139,
        16102016795: 96102016751,
        84731091580: 87031491580,
        15720759071: 75020759171,
    }
    emp_rates = {int(e['PESEL']): float(e['hourly_rate']) for _, e in employees.iterrows()}

    def parse_date(d):
        if pd.isna(d):
            return None
        try:
            return datetime.strptime(str(d), '%Y-%m-%d').date()
        except Exception:
            return None

    records = []
    for _, row in timesheet.iterrows():
        dt = parse_date(row['date'])
        if not dt:
            continue
        emp_id = int(row['employee_id']) if pd.notna(row['employee_id']) else None
        if emp_id in emp_map:
            emp_id = emp_map[emp_id]
        if emp_id not in emp_rates:
            continue
        try:
            pt = ast.literal_eval(row['performed_tasks']) if isinstance(row['performed_tasks'], str) else row['performed_tasks']
        except Exception:
            pt = []
        if pt is None:
            pt = []
        valid_tasks = []
        for tid in pt:
            try:
                tid = int(tid)
            except Exception:
                continue
            if tid in task_lookup:
                valid_tasks.append(tid)
        bonus = sum(task_lookup[tid]['pay_per_completion'] for tid in valid_tasks)
        hours = float(row['hours_worked']) if pd.notna(row['hours_worked']) else 0.0
        rate = emp_rates[emp_id]
        total = hours * rate + bonus
        records.append((emp_id, dt, total))

    by_emp_month = defaultdict(lambda: defaultdict(float))
    for emp_id, dt, total in records:
        by_emp_month[emp_id][(dt.year, dt.month)] += total

    result = {}
    for emp_id in by_emp_month:
        months = sorted(by_emp_month[emp_id].keys())
        lst = []
        for y, m in months:
            v = by_emp_month[emp_id][(y, m)]
            lst.append(int(round(v)))
        result[str(emp_id)] = lst

    result = dict(sorted(result.items()))
    return result


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
